COMPUTE-MONOID(f, h, α):
    Q ← α^h
    generators ← {σ_a : a ∈ α}
    M ← {id} ∪ generators
    queue ← list(generators)
    while queue ≠ ∅:
        τ ← queue.dequeue()
        for each σ ∈ generators:
            τ' ← σ ∘ τ
            if τ' ∉ M:
                M ← M ∪ {τ'}
                queue.enqueue(τ')
    return M

Complexity: O(|M|² · |α|^h) time, O(|M| · |α|^h) space

